/** [sql-recycle.xml] RecycleMapper.getMp02Info **/
SELECT MP02_LOT_SEQ 
FROM TB_MP_02
WHERE 1=1
AND MP02_COMPANY = #{st12Company}
AND MP02_FACTORY = #{st12Factory}
AND MP02_PCB_QR = #{st12Qr}

/** [sql-recycle.xml] RecycleMapper.duplicationRecycle **/
SELECT MAX(ST12_CNT) AS ST12_CNT
FROM TB_ST_12
WHERE 1=1
AND ST12_COMPANY = #{st12Company}
AND ST12_FACTORY = #{st12Factory}
AND ST12_MF_NO = #{st12No}

mapper.update:
/** [sql-recycle.xml] RecycleMapper.cntPlusRecycle **/
INSERT INTO TB_ST_12
(
	  ST12_COMPANY
	, ST12_FACTORY
	, ST12_MF_NO
	, ST12_CNT
	, ST12_LOT_SEQ
	, ST12_CODE
	, ST12_PCC
	, ST12_QR
	, ST12_LINE_CODE
	, ST12_EQUIP_CODE
	, ST12_INDTE
	, ST12_EMPNO
)
VALUES
(
	  #{st12Company}
	, #{st12Factory}
	, #{st12No}
	, #{st12Cnt} + 1
	, #{st12LotSeq}
	, #{st12Code}
	, #{st12Pcc}
	, #{st12Qr}
	, #{st12LineCode}
	, #{st12EquipCode}
	, SYSDATE
	, #{st12Empno}
)

